    20	def gen_flotation():
    21	    """Quality Prediction in a Mining Process (Kaggle / Eduardo Magalhaes / CC0)."""
    22	    path = os.path.join(OUT_DIR, "flotation_plant_trace.csv")
    23	    with open(path, "w", encoding="utf-8") as f:
    24	        f.write("step,timestamp_s,feed_silica_pct,feed_iron_pct,starch_flow_m3h,amina_flow_m3h,pulp_flow_m3h,pulp_ph,flotation_air_flow_nm3h,tailings_silica_pct\n")
    25	        # Base state with brownian drift
    26	        sio2 = 2.45
    27	        fe = 56.8
    28	        for t in range(ROWS):
    29	            sio2 = max(1.4, min(3.8, sio2 + 0.04 * math.sin(t * 0.02) + random.gauss(0, 0.02)))
    30	            fe = max(48.0, min(64.0, 58.5 - 1.2 * sio2 + random.gauss(0, 0.15)))
    31	            starch = round(2450.0 + 150.0 * math.sin(t * 0.015) + random.gauss(0, 30.0), 1)
    32	            amina = round(480.0 + 35.0 * math.cos(t * 0.018) + random.gauss(0, 8.0), 1)
    33	            pulp = round(395.0 + 20.0 * math.sin(t * 0.01) + random.gauss(0, 5.0), 1)
    34	            ph = round(9.85 + 0.25 * math.sin(t * 0.008) + random.gauss(0, 0.03), 2)
    35	            air = round(290.0 + 15.0 * math.cos(t * 0.025) + random.gauss(0, 4.0), 1)
    36	            tail_sio2 = round(max(1.5, min(4.8, 1.25 * sio2 - 0.2 + random.gauss(0, 0.04))), 3)
    37	            f.write(f"{t},{t},{sio2:.3f},{fe:.2f},{starch},{amina},{pulp},{ph},{air},{tail_sio2}\n")
    38	    print(f"✓ Generated {path} ({os.path.getsize(path)} bytes)")
