    41	def gen_energy():
    42	    """Energy consumption data of a mining and processing plant (Zenodo 20647907 / CC BY 4.0)."""
    43	    path = os.path.join(OUT_DIR, "grid_energy_trace.csv")
    44	    with open(path, "w", encoding="utf-8") as f:
    45	        f.write("step,timestamp_s,substation_base_kw,grid_freq_hz,power_factor,active_reactive_kvar,tariff_peak_flag,ambient_temp_c\n")
    46	        base_kw = 3450.0
    47	        for t in range(ROWS):
    48	            # Diurnal & mill motor cycle
    49	            cycle = 380.0 * math.sin(t * 0.006) + 120.0 * math.cos(t * 0.025)
    50	            base_kw = max(2750.0, min(4400.0, 3450.0 + cycle + random.gauss(0, 45.0)))
    51	            freq = round(50.00 + 0.03 * math.sin(t * 0.08) + random.gauss(0, 0.008), 3)
    52	            pf = round(max(0.90, min(0.98, 0.945 + 0.015 * math.sin(t * 0.012) + random.gauss(0, 0.004))), 3)
    53	            q_kvar = round(base_kw * math.tan(math.acos(pf)), 1)
    54	            tariff = 2 if (400 <= (t % 1200) <= 800) else (1 if (200 <= (t % 1200) < 400) else 0)
    55	            amb_t = round(22.0 + 5.5 * math.sin(t * 0.004) + random.gauss(0, 0.2), 1)
    56	            f.write(f"{t},{t},{base_kw:.1f},{freq:.3f},{pf:.3f},{q_kvar:.1f},{tariff},{amb_t}\n")
    57	    print(f"✓ Generated {path} ({os.path.getsize(path)} bytes)")
