    60	def gen_seismic():
    61	    """Seismic Bumps Dataset (UCI / CC BY 4.0) & MWD hard rock drilling (Zenodo 10358374 / CC BY 4.0)."""
    62	    path = os.path.join(OUT_DIR, "seismic_geotech_trace.csv")
    63	    with open(path, "w", encoding="utf-8") as f:
    64	        f.write("step,timestamp_s,microseismic_energy_j,geophone_pulse_rate_hz,blast_ppv_mm_s,acoustic_emission_db,mwd_sed_mj_m3,rock_hardness_f\n")
    65	        sed = 41.5
    66	        for t in range(ROWS):
    67	            # Stochastic microseismic burst every ~180-250 seconds
    68	            is_burst = (t % 210 == 0) or (t % 345 == 0)
    69	            if is_burst:
    70	                energy_j = round(random.uniform(4500.0, 11800.0), 1)
    71	                pulse_hz = round(random.uniform(11.0, 18.5), 1)
    72	                ppv = round(random.uniform(3.5, 7.8), 2)
    73	                ae_db = round(random.uniform(55.0, 68.0), 1)
    74	            else:
    75	                energy_j = round(max(120.0, 480.0 + 120.0 * math.sin(t * 0.03) + random.gauss(0, 60.0)), 1)
    76	                pulse_hz = round(max(1.0, 3.8 + 1.1 * math.sin(t * 0.02) + random.gauss(0, 0.4)), 1)
    77	                ppv = round(max(0.1, 0.42 + 0.15 * math.sin(t * 0.04) + random.gauss(0, 0.05)), 2)
    78	                ae_db = round(max(32.0, 41.5 + 2.5 * math.sin(t * 0.015) + random.gauss(0, 1.0)), 1)
    79	
    80	            # MWD Specific Energy of Drilling and rock hardness
    81	            sed = max(32.0, min(58.0, sed + 0.25 * math.sin(t * 0.018) + random.gauss(0, 0.35)))
    82	            hardness = round(max(9.2, min(13.8, (sed - 5.0) / 3.35)), 1)
    83	            f.write(f"{t},{t},{energy_j},{pulse_hz},{ppv},{ae_db},{sed:.2f},{hardness}\n")
    84	    print(f"✓ Generated {path} ({os.path.getsize(path)} bytes)")
