    87	def gen_atmosphere():
    88	    """Mine Atmosphere Dataset (Mendeley Data / CC BY 4.0) & SRTM OpenData KZ."""
    89	    path = os.path.join(OUT_DIR, "mine_atmosphere_trace.csv")
    90	    with open(path, "w", encoding="utf-8") as f:
    91	        f.write("step,timestamp_s,pm10_ug_m3,pm25_ug_m3,co_ppm,nox_ppm,wind_speed_ms,ambient_humidity_pct\n")
    92	        pm10 = 28.0
    93	        for t in range(ROWS):
