    98	            co = round(max(1.0, min(16.0, 2.8 + 0.08 * pm10 + random.gauss(0, 0.25))), 2)
    99	            nox = round(max(0.1, min(4.2, 0.65 + 0.025 * pm10 + random.gauss(0, 0.08))), 2)
   100	            wind = round(max(0.8, min(8.5, 3.4 + 1.2 * math.sin(t * 0.012) + random.gauss(0, 0.4))), 1)
   101	            hum = round(max(20.0, min(75.0, 44.0 - 8.0 * math.sin(t * 0.005) + random.gauss(0, 1.5))), 1)
   102	            f.write(f"{t},{t},{pm10:.1f},{pm25},{co},{nox},{wind},{hum}\n")
